/*
	VIOC_trackers.sqf - agregado por tools/vio_build.py (parche trackers; copia configurada, no es del autor de la
	mision). Solo servidor (init.sqf lo lanza con execVM).

	Rastreadores de la IA ENEMIGA (Oeste/Este sin jugadores), como en S.O.G. Prairie Fire: si andas por su territorio, un
	equipo pequenio sale detras de ti y sigue tu RASTRO (por donde pasaste hace VIOC_TR_DELAY s, no donde estas), hasta que
	te alcanza o le pierdes.
	  - Tu rastro: el servidor anota la posicion de cada jugador cada VIOC_TR_SAMPLE s (los ultimos 15 min).
	  - Cuando: llevas VIOC_TR_DWELL s seguidos a menos de VIOC_TR_ZONE m de un pueblo del bando enemigo (a pie o en un
	    vehiculo de tierra; nunca en el aire ni a menos de 1 km de tu HQ); cada minuto hay VIOC_TR_CHANCE de que salga un
	    equipo. Como mucho VIOC_TRACKERS equipos detras de cada jugador; despues de que uno termina, VIOC_TR_COOLDOWN s de
	    espera para ese jugador.
	  - El equipo: VIOC_TR_SQUAD soldados de las listas de pueblo de ese bando (con el equipo de la mision), con buena
	    vista y oido, que aparecen sobre tu rastro (por donde pasaste hace 5-15 min, a 450-900 m) o, si no se puede, a
	    600-900 m del lado de su pueblo; siempre en tierra, con camino sin agua hasta ti, sin que ningun jugador este a
	    menos de 400 m ni los vea. Respeta el presupuesto de IA de perf_cleanup.
	  - Siguen tu rastro en fila; a menos de VIOC_TR_CLOSE m (o si ya te vieron) van a por ti: buscar y destruir donde
	    estas, mientras sigas a menos de 600 m o te tengan localizado; si no, vuelven a tu rastro (el de hace 30 s). La primera vez que estan a menos de 350 m: "Notas movimiento a tu espalda..." en tu chat.
	  - Te pierden si te alejas mas de VIOC_TR_LOST m de ellos (un vehiculo rapido), subes a una aeronave o a una barca,
	    entras al agua, mueres (al reaparecer empiezas de cero) o tu rastro queda en el agua: vuelven a su pueblo y se borran sin jugadores a 1,5 km. Tambien se borran a los
	    VIOC_TR_TTL s si ningun jugador esta a 1 km.
	No se guardan. Parametro VIOC_TRACKERS (0 no, 1 o 2 equipos detras de cada jugador).
	Consola (LOCAL EXEC en el anfitrion): hint (call VIOC_TR_fnc_info);   call VIOC_TR_fnc_markers;   (marcadores locales)
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_TR_RUNNING") exitWith {};
VIOC_TR_RUNNING = true;
VIOC_TR_MAX = missionNamespace getVariable ["VIOC_TRACKERS", 1];
if !(VIOC_TR_MAX isEqualType 0) then {VIOC_TR_MAX = 1};
if (VIOC_TR_MAX <= 0) exitWith {diag_log "[VIOC trackers] desactivado por el parametro de lobby"};

//--- Ajustes
VIOC_TR_SQUAD = 5;            // soldados por equipo
VIOC_TR_ZONE = 1500;          // m a un pueblo enemigo para contar como su territorio
VIOC_TR_DWELL = 180;          // s seguidos en su territorio antes de que pueda salir un equipo
VIOC_TR_CHANCE = 0.3;         // probabilidad por minuto, despues de VIOC_TR_DWELL
VIOC_TR_COOLDOWN = 600;       // s de espera por jugador despues de que un equipo termina
VIOC_TR_SAMPLE = 15;          // s entre puntos del rastro
VIOC_TR_DELAY = 150;          // s: siguen por donde pasaste hace este tiempo
VIOC_TR_CLOSE = 250;          // m: mas cerca, van a por ti
VIOC_TR_LOST = 2500;          // m: mas lejos, te pierden
VIOC_TR_TTL = 1800;           // s de vida de un equipo (si ningun jugador esta a 1 km)
VIOC_TR_AI_MARGIN = 40;       // plazas del presupuesto de IA que se dejan libres
VIOC_TR_PERIOD = 10;          // s por pasada

VIOC_TR_TRAILS = createHashMap;   // uid -> [[tiempo, posicion], ...]
VIOC_TR_DWELLT = createHashMap;   // uid -> desde cuando esta en territorio enemigo (-1 = fuera)
VIOC_TR_CD = createHashMap;       // uid -> no antes de
VIOC_TR_TEAMS = [];               // HashMap: grp, side, uid, born, state ("track", "hunt", "lost"), warned, wp
VIOC_TR_HUM = [];                 // bandos que alguna vez tuvieron un jugador
VIOC_TR_POOLS = createHashMap;
VIOC_TR_INFO = [0, 0, 0];         // [equipos salidos, te alcanzaron (a menos de VIOC_TR_CLOSE), te perdieron]

//--- ---------------------------------- utilidades ----------------------------------
VIOC_TR_fnc_players = {
	private _pl = (allPlayers - (entities "HeadlessClient_F")) select {alive _x};
	if (!isMultiplayer && {hasInterface} && {!isNull player} && {alive player}) then {_pl pushBackUnique player};
	{
		private _s = side group _x;
		if (_s in [west, east]) then {VIOC_TR_HUM pushBackUnique _s};
	} forEach _pl;
	_pl
};

VIOC_TR_fnc_uid = {
	params ["_p"];
	private _u = getPlayerUID _p;
	if (_u == "") then {_u = "local"};
	_u
};

//--- [uid, jugadores] -> el jugador vivo con ese uid (o objNull)
VIOC_TR_fnc_byUid = {
	params ["_uid", "_pl"];
	private _i = _pl findIf {([_x] call VIOC_TR_fnc_uid) == _uid};
	if (_i < 0) then {objNull} else {_pl select _i}
};

//--- [posicion, jugadores] -> true si ningun jugador esta a menos de 400 m ni la ve a menos de 1500 m
VIOC_TR_fnc_hidden = {
	params ["_p", "_pl"];
	private _asl = (AGLToASL [_p select 0, _p select 1, 0]) vectorAdd [0, 0, 1.5];
	(_pl findIf {
		private _d = _x distance2D _p;
		(_d < 400) || {(_d < 1500) && {([vehicle _x, "VIEW", objNull] checkVisibility [eyePos _x, _asl]) > 0.2}}
	}) < 0
};

//--- (como VIOC_AA_fnc_room / reserve) presupuesto de IA de perf_cleanup (sin el, 650)
VIOC_TR_fnc_room = {
	params ["_n"];
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", -1];
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
	if (!(_max isEqualType 0) || {!(_cnt isEqualType 0)} || {_max < 0} || {_cnt < 0}) then {_max = 650; _cnt = {!isPlayer _x} count allUnits};
	(_cnt + _n) <= (_max - VIOC_TR_AI_MARGIN)
};
VIOC_TR_fnc_reserve = {
	params ["_n"];
	isNil {
		private _c = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
		if (_c isEqualType 0 && {_c >= 0}) then {VIOC_PERF_AI_COUNT = _c + _n};
	};
};

//--- [bando] -> [fusileros, ametralladores]: listas de pueblo del bando (<BANDO>_INFANTRY_SQ_*)
VIOC_TR_fnc_pool = {
	params ["_side"];
	private _k = str _side;
	if (_k in VIOC_TR_POOLS) exitWith {VIOC_TR_POOLS get _k};
	private _tag = ["WEST_", "EAST_"] select (_side isEqualTo east);
	private _get = {
		params ["_n"];
		private _l = missionNamespace getVariable [_tag + _n, []];
		if !(_l isEqualType []) then {_l = []};
		private _r = [];
		{
			private _c = if (_x isEqualType []) then {_x param [0, ""]} else {_x};
			if ((_c isEqualType "") && {_c != ""} && {isClass (configFile >> "CfgVehicles" >> _c)} && {_c isKindOf "CAManBase"}) then {_r pushBackUnique _c};
		} forEach _l;
		_r
	};
	private _res = [["INFANTRY_SQ_LIGHT"] call _get, ["INFANTRY_SQ_MG"] call _get];
	if (count (_res select 0) > 0) then {VIOC_TR_POOLS set [_k, _res]};
	_res
};

//--- [jugador] -> [pueblo enemigo mas cercano a menos de VIOC_TR_ZONE (o objNull), su bando]
VIOC_TR_fnc_enemyTown = {
	params ["_p", "_eids"];
	private _best = objNull;
	private _bd = VIOC_TR_ZONE;
	{
		private _d = _x distance2D _p;
		if (_d < _bd && {(_x getVariable ["cti_town_sideID", -1]) in _eids}) then {_bd = _d; _best = _x};
	} forEach (missionNamespace getVariable ["CTI_Towns", []]);
	[_best, if (isNull _best) then {sideUnknown} else {(_best getVariable ["cti_town_sideID", -1]) call CTI_CO_FNC_GetSideFromID}]
};

//--- [uid, antiguedad minima en s] -> el punto del rastro mas reciente con esa antiguedad (o [])
VIOC_TR_fnc_trailAt = {
	params ["_uid", "_age"];
	private _tr = VIOC_TR_TRAILS getOrDefault [_uid, []];
	private _res = [];
	for "_i" from ((count _tr) - 1) to 0 step -1 do {
		private _e = _tr select _i;
		if ((time - (_e select 0)) >= _age) exitWith {_res = _e select 1};
	};
	_res
};

//--- [desde, hasta] -> true si la linea recta no pasa por agua (muestras cada 50 m): hay camino a pie
VIOC_TR_fnc_dryLine = {
	params ["_a", "_b"];
	private _n = ceil ((_a distance2D _b) / 50);
	private _ok = true;
	for "_k" from 1 to (_n - 1) do {
		if (surfaceIsWater (_a vectorAdd ((_b vectorDiff _a) vectorMultiply (_k / _n)))) exitWith {_ok = false};
	};
	_ok
};

//--- [jugador, bando, pueblo enemigo, jugadores] -> equipo nuevo (o grpNull)
VIOC_TR_fnc_spawn = {
	params ["_tgt", "_side", "_town", "_pl"];
	([_side] call VIOC_TR_fnc_pool) params ["_li", "_mg"];
	if (count _li == 0) exitWith {grpNull};
	private _tp = getPosATL _tgt;
	private _dir = _tp getDir _town;
	//--- primero sobre tu rastro (detras de ti: puntos de hace 5-15 min a 450-900 m); si no, del lado de su pueblo
	private _cand = ((VIOC_TR_TRAILS getOrDefault [[_tgt] call VIOC_TR_fnc_uid, []]) select {((time - (_x select 0)) >= 300) && {((_x select 1) distance2D _tp) > 450} && {((_x select 1) distance2D _tp) < 900}}) apply {_x select 1};
	for "_i" from 0 to 29 do {_cand pushBack (_tp getPos [600 + random 300, _dir - 50 + random 100])};
	private _p = [];
	{
		private _q = (_x getPos [random 40, random 360]);
		_q = [_q select 0, _q select 1, 0];
		if (count _p == 0 && {!(surfaceIsWater _q)} && {({surfaceIsWater (_q getPos [20, _x])} count [0, 90, 180, 270]) == 0}
			&& {[_q, _tp] call VIOC_TR_fnc_dryLine}
			&& {((_q nearEntities [["CAManBase", "LandVehicle"], 300]) findIf {alive _x && {(side group _x) in VIOC_TR_HUM}}) < 0}
			&& {[_q, _pl] call VIOC_TR_fnc_hidden}) then {_p = _q};
	} forEach _cand;
	if (count _p == 0) exitWith {grpNull};
	private _cls = [selectRandom _li];
	if (count _mg > 0) then {_cls pushBack (selectRandom _mg)};
	while {count _cls < VIOC_TR_SQUAD} do {_cls pushBack (selectRandom _li)};
	private _g = createGroup [_side, true];
	if (isNull _g) exitWith {grpNull};
	{
		private _q = _p getPos [2 + random 6, random 360];
		private _u = [_x, _g, [_q select 0, _q select 1, 0], _side, false, "NONE"] call CTI_CO_FNC_CreateUnit;
		if (!isNil "_u" && {_u isEqualType objNull} && {!isNull _u}) then {
			_u setVariable ["vioc_tr", true, true];
			_u setSkill ["spotDistance", 0.85];
			_u setSkill ["spotTime", 0.8];
			_u setSkill ["courage", 0.8];
		};
	} forEach _cls;
	if (({alive _x} count (units _g)) == 0) exitWith {deleteGroup _g; grpNull};
	_g setVariable ["vioc_tr", true, true];
	_g setVariable ["vioc_specops", true, true];	//--- como el asalto aereo: ai_tactics, ai_transport, airfields y town_cleanup no la toman
	[{alive _x} count (units _g)] call VIOC_TR_fnc_reserve;
	_g setBehaviour "AWARE";
	_g setCombatMode "RED";
	_g setFormation "FILE";
	_g allowFleeing 0;
	VIOC_TR_INFO set [0, (VIOC_TR_INFO select 0) + 1];
	_g
};

//--- [equipo, posicion, tipo, radio]: un solo punto de paso
VIOC_TR_fnc_wp = {
	params ["_g", "_p", ["_type", "MOVE"], ["_r", 0]];
	{deleteWaypoint [_g, 0]} forEach (waypoints _g);
	private _w = _g addWaypoint [_p, _r];
	_w setWaypointType _type;
	_w setWaypointCompletionRadius 15;
	if (_type == "MOVE") then {_w setWaypointSpeed "NORMAL"; _w setWaypointBehaviour "AWARE"};
	_g setCurrentWaypoint _w;
};

//--- [equipo]: te perdieron; vuelven a su pueblo mas cercano
VIOC_TR_fnc_lose = {
	params ["_t", "_why"];
	if ((_t get "state") == "lost") exitWith {};
	_t set ["state", "lost"];
	VIOC_TR_INFO set [2, (VIOC_TR_INFO select 2) + 1];
	private _g = _t get "grp";
	private _l = leader _g;
	private _sid = (_t get "side") call CTI_CO_FNC_GetSideID;
	private _home = objNull;
	private _bd = 1e9;
	{
		private _d = _x distance2D _l;
		if (_d < _bd && {(_x getVariable ["cti_town_sideID", -1]) == _sid}) then {_bd = _d; _home = _x};
	} forEach (missionNamespace getVariable ["CTI_Towns", []]);
	if (!isNull _home) then {[_g, getPosATL _home] call VIOC_TR_fnc_wp};
	VIOC_TR_CD set [_t get "uid", time + VIOC_TR_COOLDOWN];
	diag_log format ["[VIOC trackers] %1 pierde el rastro (%2)", groupId _g, _why];
};

VIOC_TR_fnc_info = {
	private _l = [format ["Rastreadores: %1 equipos activos; salieron %2, te alcanzaron %3, te perdieron %4 (max %5 por jugador)", count VIOC_TR_TEAMS, VIOC_TR_INFO select 0, VIOC_TR_INFO select 1, VIOC_TR_INFO select 2, VIOC_TR_MAX]];
	{
		private _g = _x get "grp";
		_l pushBack format ["%1 (%2): %3, %4 vivos, %5 s, en %6", groupId _g, _x get "side", _x get "state", {alive _x} count (units _g), round (time - (_x get "born")), mapGridPosition (leader _g)];
	} forEach VIOC_TR_TEAMS;
	_l joinString "\n"
};

//--- Marcadores locales de los equipos y del punto al que van (prueba; en la maquina que lo ejecuta)
VIOC_TR_fnc_markers = {
	{deleteMarkerLocal _x} forEach (allMapMarkers select {(_x find "vioc_tr_mk_") == 0});
	{
		private _g = _x get "grp";
		private _m = createMarkerLocal [format ["vioc_tr_mk_%1", _forEachIndex], getPosATL (leader _g)];
		_m setMarkerTypeLocal "o_recon";
		_m setMarkerColorLocal "ColorOrange";
		_m setMarkerTextLocal format ["Rastreadores (%1)", _x get "state"];
		private _wp = _x getOrDefault ["wp", []];
		if (count _wp > 1) then {
			private _n = createMarkerLocal [format ["vioc_tr_mk_%1_w", _forEachIndex], _wp];
			_n setMarkerTypeLocal "mil_dot";
			_n setMarkerColorLocal "ColorOrange";
			_n setMarkerTextLocal "rastro";
		};
	} forEach VIOC_TR_TEAMS;
	count VIOC_TR_TEAMS
};

//--- ---------------------------------- bucle ----------------------------------
waitUntil {sleep 2; !isNil "CTI_Init_Server" && {!isNil "CTI_InitTowns"}};
diag_log format ["[VIOC trackers] activo: hasta %1 equipos detras de cada jugador", VIOC_TR_MAX];
private _nextSample = 0;
private _nextRoll = time + 60;

while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
	private _pl = call VIOC_TR_fnc_players;
	private _hids = VIOC_TR_HUM apply {_x call CTI_CO_FNC_GetSideID};
	private _eids = [CTI_WEST_ID, CTI_EAST_ID] - _hids;

	//--- rastro de cada jugador (los ultimos 15 min)
	if (time >= _nextSample) then {
		_nextSample = time + VIOC_TR_SAMPLE;
		{
			private _uid = [_x] call VIOC_TR_fnc_uid;
			private _tr = VIOC_TR_TRAILS getOrDefault [_uid, []];
			_tr pushBack [time, getPosATL (vehicle _x)];
			if (count _tr > 60) then {_tr deleteAt 0};
			VIOC_TR_TRAILS set [_uid, _tr];
		} forEach _pl;
	};

	//--- equipos: seguir el rastro, ir a por ti, perderte, borrarse
	{
		private _t = _x;
		private _g = _t get "grp";
		private _alive = (units _g) select {alive _x};
		if (count _alive == 0) then {
			_t set ["gone", true];
			if ((_t get "state") != "lost") then {VIOC_TR_CD set [_t get "uid", time + VIOC_TR_COOLDOWN]};
		} else {
			private _l = leader _g;
			private _near = (_alive findIf {private _u = _x; (_pl findIf {(_x distance2D _u) < 1500}) >= 0}) >= 0;
			private _near1k = (_alive findIf {private _u = _x; (_pl findIf {(_x distance2D _u) < 1000}) >= 0}) >= 0;
			if ((_t get "state") == "lost") then {
				if (!_near) then {_t set ["gone", true]};
			} else {
				private _tgt = [_t get "uid", _pl] call VIOC_TR_fnc_byUid;
				private _d = 1e9;
				if (!isNull _tgt) then {{_d = _d min (_x distance2D _tgt)} forEach _alive};
				switch (true) do {
					case (isNull _tgt || {!(_tgt isEqualTo (_t get "tgt"))}): {[_t, "el jugador murio o se fue"] call VIOC_TR_fnc_lose};
					case ((vehicle _tgt) isKindOf "Air"): {[_t, "subio a una aeronave"] call VIOC_TR_fnc_lose};
					case (((vehicle _tgt) isKindOf "Ship") || {surfaceIsWater (getPosATL _tgt)}): {[_t, "se fue por el agua"] call VIOC_TR_fnc_lose};
					case (_d > VIOC_TR_LOST): {[_t, "demasiado lejos"] call VIOC_TR_fnc_lose};
					case ((time - (_t get "born")) > VIOC_TR_TTL && {!_near1k}): {[_t, "tiempo agotado"] call VIOC_TR_fnc_lose};
					case ((_d < VIOC_TR_CLOSE) || {(_l knowsAbout (vehicle _tgt)) >= 1.5} || {((_t get "state") == "hunt") && {_d < 600}}): {
						//--- a por ti: buscar y destruir donde estas (con algo de error)
						if ((_t get "state") != "hunt") then {
							_t set ["state", "hunt"];
							VIOC_TR_INFO set [1, (VIOC_TR_INFO select 1) + 1];
							_g setBehaviour "COMBAT";
							_g setFormation "WEDGE";
						};
						_g reveal [vehicle _tgt, 1.5];
						private _ref = getPosATL _tgt;
						if ((_ref distance2D (_t getOrDefault ["wpRef", [0, 0, 0]])) > 40) then {
							private _q = _ref getPos [random 30, random 360];
							[_g, _q, "SAD", 30] call VIOC_TR_fnc_wp;
							_t set ["wp", _q];
							_t set ["wpRef", _ref];
						};
					};
					default {
						//--- siguen el rastro: por donde pasaste hace VIOC_TR_DELAY s (30 s si te acaban de perder de vista)
						private _age = VIOC_TR_DELAY;
						if ((_t get "state") == "hunt") then {
							_t set ["state", "track"];
							_t set ["wpRef", [0, 0, 0]];
							_g setBehaviour "AWARE";
							_g setFormation "FILE";
							_age = 30;
						};
						private _q = [_t get "uid", _age] call VIOC_TR_fnc_trailAt;
						if (count _q == 0) then {_q = [_t get "uid", 0] call VIOC_TR_fnc_trailAt};
						if (count _q > 1 && {surfaceIsWater _q}) then {
							[_t, "el rastro se pierde en el agua"] call VIOC_TR_fnc_lose;
						} else {
							if (count _q > 1 && {(_q distance2D (_t getOrDefault ["wp", [0, 0, 0]])) > 40}) then {
								[_g, _q] call VIOC_TR_fnc_wp;
								_t set ["wp", _q];
							};
						};
					};
				};
				if (!(_t get "warned") && {_d < 350}) then {
					_t set ["warned", true];
					["Notas movimiento a tu espalda... puede que alguien siga tu rastro."] remoteExec ["systemChat", _tgt];
				};
			};
		};
		if (_t getOrDefault ["gone", false]) then {
			{if (alive _x) then {deleteVehicle _x}} forEach (units _g);
		};
	} forEach VIOC_TR_TEAMS;
	VIOC_TR_TEAMS = VIOC_TR_TEAMS select {!(_x getOrDefault ["gone", false])};

	//--- territorio enemigo y equipos nuevos (tirada cada minuto); los muertos empiezan de cero al reaparecer
	private _uids = _pl apply {[_x] call VIOC_TR_fnc_uid};
	{if !(_x in _uids) then {VIOC_TR_DWELLT set [_x, -1]}} forEach (keys VIOC_TR_DWELLT);
	private _roll = time >= _nextRoll;
	if (_roll) then {_nextRoll = time + 60};
	{
		private _p = _x;
		private _uid = [_p] call VIOC_TR_fnc_uid;
		private _v = vehicle _p;
		private _hq = (side group _p) call CTI_CO_FNC_GetSideHQ;
		private _atHome = !isNil "_hq" && {_hq isEqualType objNull} && {!isNull _hq} && {(_hq distance2D _p) < 1000};
		([_p, _eids] call VIOC_TR_fnc_enemyTown) params ["_town", "_side"];
		if (isNull _town || {_v isKindOf "Air"} || {_v isKindOf "Ship"} || {surfaceIsWater (getPosATL _p)} || {_atHome} || {!(_side in [west, east])}) then {
			VIOC_TR_DWELLT set [_uid, -1];
		} else {
			private _since = VIOC_TR_DWELLT getOrDefault [_uid, -1];
			if (_since < 0) then {VIOC_TR_DWELLT set [_uid, time]; _since = time};
			if (_roll && {(time - _since) >= VIOC_TR_DWELL} && {time >= (VIOC_TR_CD getOrDefault [_uid, 0])}
				&& {({(_x get "uid") == _uid} count VIOC_TR_TEAMS) < VIOC_TR_MAX}
				&& {(random 1) < VIOC_TR_CHANCE} && {[VIOC_TR_SQUAD] call VIOC_TR_fnc_room}) then {
				private _g = [_p, _side, _town, _pl] call VIOC_TR_fnc_spawn;
				if (!isNull _g) then {
					VIOC_TR_TEAMS pushBack (createHashMapFromArray [["grp", _g], ["side", _side], ["uid", _uid], ["born", time], ["state", "track"], ["warned", false], ["wp", [0, 0, 0]], ["tgt", _p]]);
					VIOC_TR_CD set [_uid, time + 120];	//--- el siguiente, si cabe, no antes de 2 min
					diag_log format ["[VIOC trackers] equipo de %1 (%2 soldados) tras %3, desde %4", _side, {alive _x} count (units _g), name _p, _town getVariable ["cti_town_name", "?"]];
				};
			};
		};
	} forEach _pl;
	sleep VIOC_TR_PERIOD;
};

class VIOC_TRACKERS {
	title = "VIOC: Rastreadores enemigos (siguen tu rastro si andas por su territorio)";
	values[] = {0,1,2};
	texts[] = {"No","1 equipo detras de cada jugador","2 equipos detras de cada jugador"};
	default = 1;
};
